insert into public.content (collection, id, draft, published, updated_at) values ('faqs', 'absage', '{"id":"absage","title":"Wie kann ich einen Termin absagen?","body":"Bitte beachten Sie, dass wir vereinbarte Termine ausschließlich für Sie reserviert halten. Sollten Sie doch zur Stornierung gezwungen sein, können wir das verstehen und bitten Sie, Ihren Therapeuten/Ihre Therapeutin direkt zu verständigen oder Ihre Absage schriftlich an info@citypraxis.wien zu schicken.\n\nWir ersuchen Sie um Ihr Verständnis, dass wir bei Terminen, die nicht bis spätestens werktags 24 Stunden vor dem vereinbarten Termin abgesagt werden, den vollen Preis der gebuchten Behandlung verrechnen.\n\nVielen Dank für Ihr Verständnis!","order":4,"sourceUrl":"https://citypraxis.wien/","sourceDate":"2026-09-15","titleEn":"How can I cancel an appointment?","bodyEn":"Please note that we reserve agreed appointments exclusively for you. If you need to cancel, we understand and ask you to inform your therapist directly or send your cancellation in writing to info@citypraxis.wien.\n\nWe ask for your understanding that appointments not cancelled at least 24 hours in advance on working days will be charged at the full price of the booked treatment.\n\nThank you for your understanding!"}'::jsonb, '{"id":"absage","title":"Wie kann ich einen Termin absagen?","body":"Bitte beachten Sie, dass wir vereinbarte Termine ausschließlich für Sie reserviert halten. Sollten Sie doch zur Stornierung gezwungen sein, können wir das verstehen und bitten Sie, Ihren Therapeuten/Ihre Therapeutin direkt zu verständigen oder Ihre Absage schriftlich an info@citypraxis.wien zu schicken.\n\nWir ersuchen Sie um Ihr Verständnis, dass wir bei Terminen, die nicht bis spätestens werktags 24 Stunden vor dem vereinbarten Termin abgesagt werden, den vollen Preis der gebuchten Behandlung verrechnen.\n\nVielen Dank für Ihr Verständnis!","order":4,"sourceUrl":"https://citypraxis.wien/","sourceDate":"2026-09-15","titleEn":"How can I cancel an appointment?","bodyEn":"Please note that we reserve agreed appointments exclusively for you. If you need to cancel, we understand and ask you to inform your therapist directly or send your cancellation in writing to info@citypraxis.wien.\n\nWe ask for your understanding that appointments not cancelled at least 24 hours in advance on working days will be charged at the full price of the booked treatment.\n\nThank you for your understanding!"}'::jsonb, '2026-09-15 14:33:49'::timestamptz)
on conflict (collection, id) do update set
  draft = excluded.draft,
  published = excluded.published,
  updated_at = excluded.updated_at;

insert into public.content (collection, id, draft, published, updated_at) values ('faqs', 'erstattung', '{"id":"erstattung","title":"Wie funktioniert die Rückerstattung?","body":"Nach Abschluss Ihrer Behandlung können Sie Ihre Einzelrechnungen gemeinsam mit Ihrem Verordnungsschein bei Ihrer Krankenkasse zur Rückerstattung einreichen bzw. anschließend bei Ihrer privaten Zusatzversicherung geltend machen.","order":2,"sourceUrl":"https://citypraxis.wien/","sourceDate":"2026-09-15","titleEn":"How does reimbursement work?","bodyEn":"After completing your treatment, you can submit your individual invoices together with your referral to your health insurer for reimbursement and subsequently claim through your private supplementary insurance."}'::jsonb, '{"id":"erstattung","title":"Wie funktioniert die Rückerstattung?","body":"Nach Abschluss Ihrer Behandlung können Sie Ihre Einzelrechnungen gemeinsam mit Ihrem Verordnungsschein bei Ihrer Krankenkasse zur Rückerstattung einreichen bzw. anschließend bei Ihrer privaten Zusatzversicherung geltend machen.","order":2,"sourceUrl":"https://citypraxis.wien/","sourceDate":"2026-09-15","titleEn":"How does reimbursement work?","bodyEn":"After completing your treatment, you can submit your individual invoices together with your referral to your health insurer for reimbursement and subsequently claim through your private supplementary insurance."}'::jsonb, '2026-09-15 14:33:49'::timestamptz)
