insert into public.content (collection, id, draft, published, updated_at) values ('faqs', 'ersttermin', '{"id":"ersttermin","title":"Was bringe ich zum ersten Termin mit?","body":"Bitte bringen Sie zum Ersttermin aktuelle Befunde & Bilder zu Ihren Beschwerden (Röntgen, CT, MRT, Arztbriefe, Rehabericht, etc.) mit.\n\nSie benötigen keinerlei spezielle Sportbekleidung beim Ersttermin, allerdings empfehlen wir Ihnen bequeme Kleidung für die Erstuntersuchung zu tragen.","order":1,"sourceUrl":"https://citypraxis.wien/","sourceDate":"2026-09-15","titleEn":"What should I bring to my first appointment?","bodyEn":"Please bring current findings and images relating to your symptoms to your first appointment (X-rays, CT, MRI, medical letters, rehabilitation reports, etc.).\n\nYou do not need any special sportswear for your first appointment, but we recommend comfortable clothing for the initial examination."}'::jsonb, '{"id":"ersttermin","title":"Was bringe ich zum ersten Termin mit?","body":"Bitte bringen Sie zum Ersttermin aktuelle Befunde & Bilder zu Ihren Beschwerden (Röntgen, CT, MRT, Arztbriefe, Rehabericht, etc.) mit.\n\nSie benötigen keinerlei spezielle Sportbekleidung beim Ersttermin, allerdings empfehlen wir Ihnen bequeme Kleidung für die Erstuntersuchung zu tragen.","order":1,"sourceUrl":"https://citypraxis.wien/","sourceDate":"2026-09-15","titleEn":"What should I bring to my first appointment?","bodyEn":"Please bring current findings and images relating to your symptoms to your first appointment (X-rays, CT, MRI, medical letters, rehabilitation reports, etc.).\n\nYou do not need any special sportswear for your first appointment, but we recommend comfortable clothing for the initial examination."}'::jsonb, '2026-09-15 14:33:49'::timestamptz)
