insert into public.content (collection, id, draft, published, updated_at) values ('faqs', 'zahlung', '{"id":"zahlung","title":"Wie kann ich bezahlen?","body":"Wir bitten Sie, jede Behandlung direkt nach dem Termin in bar zu bezahlen  – wir haben keine Bankomatkasse!","order":3,"sourceUrl":"https://citypraxis.wien/","sourceDate":"2026-09-15","titleEn":"How can I pay?","bodyEn":"Please pay for each treatment in cash immediately after your appointment — we do not have a card terminal!"}'::jsonb, '{"id":"zahlung","title":"Wie kann ich bezahlen?","body":"Wir bitten Sie, jede Behandlung direkt nach dem Termin in bar zu bezahlen  – wir haben keine Bankomatkasse!","order":3,"sourceUrl":"https://citypraxis.wien/","sourceDate":"2026-09-15","titleEn":"How can I pay?","bodyEn":"Please pay for each treatment in cash immediately after your appointment — we do not have a card terminal!"}'::jsonb, '2026-09-15 14:33:49'::timestamptz)
