insert into public.content (collection, id, draft, published, updated_at) values ('services', 'cmd', '{"title":"Craniomandibuläres Konzept (CMD)","tag":"KIEFERGELENK & VERBINDENDE STRUKTUREN","intro":"Unter craniomandibulärem Konzept, versteht man Techniken, die sich ausschließlich mit Dysfunktionen des Kiefergelenks und ihm verbindenden Strukturen, wie dem Schädelknochen (Cranium = Schädel, Mandibula = Unterkieferknochen) beschäftigen. Es werden manuelle Techniken und Untersuchungen unter Berücksichtigung biomechanischer Aspekte, Anatomie & Physiologie, sowie aller nervalen Strukturen (spezifisch denen, die zum Kiefergelenk führen) angewendet.","body":"## CMD(=Craniomandibuläre Dysfunktion) Konzept findet vor allem Anwendung bei:\n\n- Kieferoperationen, Kieferfrakturen, Kieferklemme, Kiefersperre, Discusverlagerung Kiefer, Kieferknacken, Zähneknirschen, Pressen der Zähne (Bruxismus), etc.\n- Migräne, Tinnitus, HNO-Problematiken, Schluckbeschwerden, etc.","image":"/assets/service-cmd.jpg","order":12,"id":"cmd","sourceUrl":"https://citypraxis.wien/","sourceDate":"2026-09-15","titleEn":"Craniomandibular concept (CMD)","tagEn":"JAW JOINT & CONNECTED STRUCTURES","introEn":"The craniomandibular concept refers to techniques concerned exclusively with dysfunctions of the temporomandibular joint and connected structures such as the skull (cranium = skull, mandible = lower jawbone). Manual techniques and examinations are used, taking into account biomechanics, anatomy and physiology, and all neural structures, particularly those leading to the temporomandibular joint.","bodyEn":"## The CMD (= craniomandibular dysfunction) concept is mainly used for:\n\n- Jaw operations, jaw fractures, trismus, locked jaw, displacement of the jaw joint disc, jaw clicking, teeth grinding, teeth clenching (bruxism), etc.\n- Migraine, tinnitus, ENT problems, swallowing difficulties, etc."}'::jsonb, '{"title":"Craniomandibuläres Konzept (CMD)","tag":"KIEFERGELENK & VERBINDENDE STRUKTUREN","intro":"Unter craniomandibulärem Konzept, versteht man Techniken, die sich ausschließlich mit Dysfunktionen des Kiefergelenks und ihm verbindenden Strukturen, wie dem Schädelknochen (Cranium = Schädel, Mandibula = Unterkieferknochen) beschäftigen. Es werden manuelle Techniken und Untersuchungen unter Berücksichtigung biomechanischer Aspekte, Anatomie & Physiologie, sowie aller nervalen Strukturen (spezifisch denen, die zum Kiefergelenk führen) angewendet.","body":"## CMD(=Craniomandibuläre Dysfunktion) Konzept findet vor allem Anwendung bei:\n\n- Kieferoperationen, Kieferfrakturen, Kieferklemme, Kiefersperre, Discusverlagerung Kiefer, Kieferknacken, Zähneknirschen, Pressen der Zähne (Bruxismus), etc.\n- Migräne, Tinnitus, HNO-Problematiken, Schluckbeschwerden, etc.","image":"/assets/service-cmd.jpg","order":12,"id":"cmd","sourceUrl":"https://citypraxis.wien/","sourceDate":"2026-09-15","titleEn":"Craniomandibular concept (CMD)","tagEn":"JAW JOINT & CONNECTED STRUCTURES","introEn":"The craniomandibular concept refers to techniques concerned exclusively with dysfunctions of the temporomandibular joint and connected structures such as the skull (cranium = skull, mandible = lower jawbone). Manual techniques and examinations are used, taking into account biomechanics, anatomy and physiology, and all neural structures, particularly those leading to the temporomandibular joint.","bodyEn":"## The CMD (= craniomandibular dysfunction) concept is mainly used for:\n\n- Jaw operations, jaw fractures, trismus, locked jaw, displacement of the jaw joint disc, jaw clicking, teeth grinding, teeth clenching (bruxism), etc.\n- Migraine, tinnitus, ENT problems, swallowing difficulties, etc."}'::jsonb, '2026-09-15 18:54:07'::timestamptz)
on conflict (collection, id) do update set
