  published = excluded.published,
  updated_at = excluded.updated_at;

insert into public.content (collection, id, draft, published, updated_at) values ('services', 'crafta', '{"title":"Craniofaziale Therapie (CRAFTA®)","tag":"KIEFER · KOPF · HALSWIRBELSÄULE","intro":"CRAFTA® ist ein spezifisches manualtherapeutisches Behandlungskonzept, das sich mit der Therapie von Gesicht, Schädel, Kiefergelenk, Hirnnerven und der Halswirbelsäule bei Erwachsenen und Kleinkindern (auch Babys) beschäftigt. Der interdisziplinäre Ansatz in Diagnostik und Therapie von craniomandibulären und craniofazialen Problemen wird mit diesem patientenorientierten Konzept gut ergänzt.","body":"## CRAFTA® hilft v.a. bei:\n\n### Allen Arten von Kiefergelenksproblemen:\n\nKieferknacken, Zähneknirschen, Störungen bei Mundöffnung, Mundschluß (Kieferklemme, Kiefersperre), nach /vor Kieferoperation, Begleitung von Zahnspange, bei Kieferfehlstellungen (Kreuzbiss, offener Biss), Kieferbruch, atypische Zahnschmerzen, etc.\n\n### Allen Arten von Kopfschmerzen:\n\nSpannungskopfschmerzen, Migräne (mit und ohne Aura), kindliche Migränearten, vestibuläre Migräne, Clusterkopfschmerzen, zervikale Kopfschmerzen sowie Nackenverspannungen und Nacken-schmerzen, etc.\n\n### Allen Formen von Schwindel:\n\nGutartiger Lagerungsschwindel (= BPLS), Morbus Meniére, Neuritis vestibularis, Zervikogener Schwindel, vestibuläre Migräne, Schwank-schwindel, Phobischer Schwindel, Polyneuropathischer Schwindel, Okkulärer Schwindel, etc.\n\n### Problemen im HNO- und Augenbereich:\n\nSchluckbeschwerden, Schnarchen, Tinnitus, Hörsturz, Gleichgewichts-probleme, Gesichtslähmungen wie Facialisparese, Trigeminus Neuralgie, Sinusitis, Augenschmerzen, Augenzucken, Schielen, Mittelohrentzündung, Druck in den Ohren/belegten Ohren, etc.\n\n### Schädeltraumata (auch bei Babys nach der Geburt):\n\nGehirnerschütterung, Schädelfrakturen, Assymetrien, Schiefhals, etc.\n\n### Problemen im Bereich der Halswirbelsäule:\n\nZervikalsyndrom, Streckfehlhaltung der Halswirbelsäule, Schleudertraumata, Bandscheibenvorfall/ Bandscheibenprolaps, etc.\n\n### Hirnnervenprobleme jeglicher Art:\n\nZungenprobleme, Sensibilitätsstörungen der Zunge, des Gesichts, des Rachens oder vom Hals; Neuralgien und Lähmungen im Gesicht, Schluckprobleme, Stimmprobleme, Doppelbilder, etc.","image":"/assets/service-crafta.jpg","order":11,"id":"crafta","sourceUrl":"https://citypraxis.wien/","sourceDate":"2026-09-15","titleEn":"Craniofacial therapy (CRAFTA®)","tagEn":"HEAD, JAW & NECK","introEn":"CRAFTA® is a specific manual therapy concept concerned with treating the face, skull, temporomandibular joint, cranial nerves and cervical spine in adults and young children (including babies). This patient-centred concept complements the interdisciplinary approach to diagnosing and treating craniomandibular and craniofacial problems.","bodyEn":"## CRAFTA® helps particularly with:\n\n### All kinds of temporomandibular joint problems:\n\nJaw clicking, teeth grinding, difficulty opening or closing the mouth (trismus, locked jaw), before and after jaw surgery, support during orthodontic treatment, jaw misalignment (crossbite, open bite), jaw fracture, atypical tooth pain, etc.\n\n### All kinds of headaches:\n\nTension headaches, migraine (with and without aura), childhood forms of migraine, vestibular migraine, cluster headaches, cervical headaches, neck tension and neck pain, etc.\n\n### All forms of dizziness:\n\nBenign paroxysmal positional vertigo (= BPPV), Ménière''s disease, vestibular neuritis, cervicogenic dizziness, vestibular migraine, swaying dizziness, phobic dizziness, polyneuropathic dizziness, ocular dizziness, etc.\n\n### Problems involving the ears, nose, throat and eyes:\n\nSwallowing difficulties, snoring, tinnitus, sudden hearing loss, balance problems, facial paralysis such as facial nerve palsy, trigeminal neuralgia, sinusitis, eye pain, eye twitching, squinting, middle ear infection, pressure in the ears/blocked ears, etc.\n\n### Skull trauma (including in babies after birth):\n\nConcussion, skull fractures, asymmetries, torticollis, etc.\n\n### Cervical spine problems:\n\nCervical syndrome, straightening of the cervical spine, whiplash, herniated/prolapsed discs, etc.\n\n### Cranial nerve problems of all kinds:\n\nTongue problems, sensory disturbances of the tongue, face, pharynx or throat; facial neuralgia and paralysis, swallowing problems, voice problems, double vision, etc."}'::jsonb, '{"title":"Craniofaziale Therapie (CRAFTA®)","tag":"KIEFER · KOPF · HALSWIRBELSÄULE","intro":"CRAFTA® ist ein spezifisches manualtherapeutisches Behandlungskonzept, das sich mit der Therapie von Gesicht, Schädel, Kiefergelenk, Hirnnerven und der Halswirbelsäule bei Erwachsenen und Kleinkindern (auch Babys) beschäftigt. Der interdisziplinäre Ansatz in Diagnostik und Therapie von craniomandibulären und craniofazialen Problemen wird mit diesem patientenorientierten Konzept gut ergänzt.","body":"## CRAFTA® hilft v.a. bei:\n\n### Allen Arten von Kiefergelenksproblemen:\n\nKieferknacken, Zähneknirschen, Störungen bei Mundöffnung, Mundschluß (Kieferklemme, Kiefersperre), nach /vor Kieferoperation, Begleitung von Zahnspange, bei Kieferfehlstellungen (Kreuzbiss, offener Biss), Kieferbruch, atypische Zahnschmerzen, etc.\n\n### Allen Arten von Kopfschmerzen:\n\nSpannungskopfschmerzen, Migräne (mit und ohne Aura), kindliche Migränearten, vestibuläre Migräne, Clusterkopfschmerzen, zervikale Kopfschmerzen sowie Nackenverspannungen und Nacken-schmerzen, etc.\n\n### Allen Formen von Schwindel:\n\nGutartiger Lagerungsschwindel (= BPLS), Morbus Meniére, Neuritis vestibularis, Zervikogener Schwindel, vestibuläre Migräne, Schwank-schwindel, Phobischer Schwindel, Polyneuropathischer Schwindel, Okkulärer Schwindel, etc.\n\n### Problemen im HNO- und Augenbereich:\n\nSchluckbeschwerden, Schnarchen, Tinnitus, Hörsturz, Gleichgewichts-probleme, Gesichtslähmungen wie Facialisparese, Trigeminus Neuralgie, Sinusitis, Augenschmerzen, Augenzucken, Schielen, Mittelohrentzündung, Druck in den Ohren/belegten Ohren, etc.\n\n### Schädeltraumata (auch bei Babys nach der Geburt):\n\nGehirnerschütterung, Schädelfrakturen, Assymetrien, Schiefhals, etc.\n\n### Problemen im Bereich der Halswirbelsäule:\n\nZervikalsyndrom, Streckfehlhaltung der Halswirbelsäule, Schleudertraumata, Bandscheibenvorfall/ Bandscheibenprolaps, etc.\n\n### Hirnnervenprobleme jeglicher Art:\n\nZungenprobleme, Sensibilitätsstörungen der Zunge, des Gesichts, des Rachens oder vom Hals; Neuralgien und Lähmungen im Gesicht, Schluckprobleme, Stimmprobleme, Doppelbilder, etc.","image":"/assets/service-crafta.jpg","order":11,"id":"crafta","sourceUrl":"https://citypraxis.wien/","sourceDate":"2026-09-15","titleEn":"Craniofacial therapy (CRAFTA®)","tagEn":"HEAD, JAW & NECK","introEn":"CRAFTA® is a specific manual therapy concept concerned with treating the face, skull, temporomandibular joint, cranial nerves and cervical spine in adults and young children (including babies). This patient-centred concept complements the interdisciplinary approach to diagnosing and treating craniomandibular and craniofacial problems.","bodyEn":"## CRAFTA® helps particularly with:\n\n### All kinds of temporomandibular joint problems:\n\nJaw clicking, teeth grinding, difficulty opening or closing the mouth (trismus, locked jaw), before and after jaw surgery, support during orthodontic treatment, jaw misalignment (crossbite, open bite), jaw fracture, atypical tooth pain, etc.\n\n### All kinds of headaches:\n\nTension headaches, migraine (with and without aura), childhood forms of migraine, vestibular migraine, cluster headaches, cervical headaches, neck tension and neck pain, etc.\n\n### All forms of dizziness:\n\nBenign paroxysmal positional vertigo (= BPPV), Ménière''s disease, vestibular neuritis, cervicogenic dizziness, vestibular migraine, swaying dizziness, phobic dizziness, polyneuropathic dizziness, ocular dizziness, etc.\n\n### Problems involving the ears, nose, throat and eyes:\n\nSwallowing difficulties, snoring, tinnitus, sudden hearing loss, balance problems, facial paralysis such as facial nerve palsy, trigeminal neuralgia, sinusitis, eye pain, eye twitching, squinting, middle ear infection, pressure in the ears/blocked ears, etc.\n\n### Skull trauma (including in babies after birth):\n\nConcussion, skull fractures, asymmetries, torticollis, etc.\n\n### Cervical spine problems:\n\nCervical syndrome, straightening of the cervical spine, whiplash, herniated/prolapsed discs, etc.\n\n### Cranial nerve problems of all kinds:\n\nTongue problems, sensory disturbances of the tongue, face, pharynx or throat; facial neuralgia and paralysis, swallowing problems, voice problems, double vision, etc."}'::jsonb, '2026-09-15 18:54:07'::timestamptz)
