insert into public.content (collection, id, draft, published, updated_at) values ('services', 'faszienbehandlungen', '{"title":"Faszienbehandlungen","tag":"FDM & FASZIENMODULATION","intro":"Faszien sind ein Teil des menschlichen Bindegewebes und umgeben Strukturen im gesamten Körper (Muskelhüllen, Organe, Bänder, etc.). Bei Verletzungen jeglicher Art ist somit auch eine Verletzung im Bereich der Faszien zu erwarten.","body":"## Fasziendistorsionsmodell (FDM)\n\nFDM ist eine intensive, teilweise schmerzhafte und rasch wirkende, sowie effektive Therapiemaßnahme, die sowohl im Akutbereich als auch im chronischen Beschwerdebereich zur Anwendung kommt. Gearbeitet wird bei dieser Technik hauptsächlich mit dem Daumen oder der Handfläche. Durch gezielte Handgriffe oder manualtherapeutische Mobilisationen an den Gelenken wird versucht, das Bindegewebe wieder in seine physiologische Ursprungsform zu bringen, um so dessen optimalen Wirkeffekt wiederherzustellen.\n\n## 1.2 Faszienmodulation (FM):\n\nDiese Behandlungsmethode befasst sich ebenso mit dem Bindewegebe, v.a. den tiefen Faszien. Sie stellt ebenso wie die FDM-Methode eine intensive und sehr effektive Behandlung bei vielfältigen Beschwerden dar. Anhand spezieller Bewegungsgstests und Palpationen werden die Bereiche erhöhter Spannung in der Faszie am ganzen Körper ermittelt und durch Druck und gleichzeitige Reibung behandelt. Bei den speziellen Tests werden auch alle früheren Verletzungen mitberücksichtigt, die in weiterer Folge Einfluss auf andere bindewegebige Strukturen darstellen und somit in der Kausalitätskette von größter Bedeutung sind und dementsprechend auch mitbehandelt werden müssen\n\n## Typische Beschwerden, bei denen Faszienbehandlungen helfen können\n\n- Alle hartnäckigen, langwierigen Probleme, für die sonst kaum eine Ursache gefunden werden kann\n- Häufige Probleme wie: Fersensporn,Tennis-/Golferellbogen, Achillessehnenproblematik, Schleimbeutelentzündungen, Ischias-probleme, etc.\n- Sportverletzungen aller Art: Supinationstrauma, Knieverletzungen, Hüftschmerzen, Schulterluxation, etc.","image":"/assets/service-physio.jpg","order":10,"id":"faszienbehandlungen","sourceUrl":"https://citypraxis.wien/","sourceDate":"2026-09-15","titleEn":"Fascial treatments","tagEn":"FASCIAL THERAPY","introEn":"Fascia is part of human connective tissue and surrounds structures throughout the body (muscle sheaths, organs, ligaments, etc.). Any injury therefore also involves injury to the fascia.","bodyEn":"## 1.1 Fascial distortion model (= FDM)\n\nFDM is an intensive, sometimes painful and fast-acting, effective therapeutic approach used for both acute and chronic symptoms. This technique mainly uses the thumbs or the palm of the hand. Targeted manual techniques or manual therapeutic joint mobilisation are used to try to return the connective tissue to its original physiological shape and restore its optimal function.\n\n## 1.2 Fascial manipulation (FM)\n\nThis treatment method focuses mainly on connective tissue, particularly the deep fascia. Like FDM, it is an intensive and very effective treatment for a wide range of symptoms. Special movement tests and palpation identify areas of increased fascial tension throughout the body, which are treated with pressure and simultaneous friction. These specific tests also take earlier injuries into account: these may subsequently influence other connective-tissue structures and therefore be important within the chain of causes, requiring treatment as well.\n\n## Typical symptoms for which fascial treatment can help\n\n- All stubborn, longstanding problems for which a cause can hardly be found\n- Common problems such as heel spurs, tennis/golfer''s elbow, Achilles tendon problems, bursitis and sciatic pain, etc.\n- Sports injuries of all kinds: ankle sprains, knee injuries, hip pain, shoulder dislocation, etc."}'::jsonb, '{"title":"Faszienbehandlungen","tag":"FDM & FASZIENMODULATION","intro":"Faszien sind ein Teil des menschlichen Bindegewebes und umgeben Strukturen im gesamten Körper (Muskelhüllen, Organe, Bänder, etc.). Bei Verletzungen jeglicher Art ist somit auch eine Verletzung im Bereich der Faszien zu erwarten.","body":"## Fasziendistorsionsmodell (FDM)\n\nFDM ist eine intensive, teilweise schmerzhafte und rasch wirkende, sowie effektive Therapiemaßnahme, die sowohl im Akutbereich als auch im chronischen Beschwerdebereich zur Anwendung kommt. Gearbeitet wird bei dieser Technik hauptsächlich mit dem Daumen oder der Handfläche. Durch gezielte Handgriffe oder manualtherapeutische Mobilisationen an den Gelenken wird versucht, das Bindegewebe wieder in seine physiologische Ursprungsform zu bringen, um so dessen optimalen Wirkeffekt wiederherzustellen.\n\n## 1.2 Faszienmodulation (FM):\n\nDiese Behandlungsmethode befasst sich ebenso mit dem Bindewegebe, v.a. den tiefen Faszien. Sie stellt ebenso wie die FDM-Methode eine intensive und sehr effektive Behandlung bei vielfältigen Beschwerden dar. Anhand spezieller Bewegungsgstests und Palpationen werden die Bereiche erhöhter Spannung in der Faszie am ganzen Körper ermittelt und durch Druck und gleichzeitige Reibung behandelt. Bei den speziellen Tests werden auch alle früheren Verletzungen mitberücksichtigt, die in weiterer Folge Einfluss auf andere bindewegebige Strukturen darstellen und somit in der Kausalitätskette von größter Bedeutung sind und dementsprechend auch mitbehandelt werden müssen\n\n## Typische Beschwerden, bei denen Faszienbehandlungen helfen können\n\n- Alle hartnäckigen, langwierigen Probleme, für die sonst kaum eine Ursache gefunden werden kann\n- Häufige Probleme wie: Fersensporn,Tennis-/Golferellbogen, Achillessehnenproblematik, Schleimbeutelentzündungen, Ischias-probleme, etc.\n- Sportverletzungen aller Art: Supinationstrauma, Knieverletzungen, Hüftschmerzen, Schulterluxation, etc.","image":"/assets/service-physio.jpg","order":10,"id":"faszienbehandlungen","sourceUrl":"https://citypraxis.wien/","sourceDate":"2026-09-15","titleEn":"Fascial treatments","tagEn":"FASCIAL THERAPY","introEn":"Fascia is part of human connective tissue and surrounds structures throughout the body (muscle sheaths, organs, ligaments, etc.). Any injury therefore also involves injury to the fascia.","bodyEn":"## 1.1 Fascial distortion model (= FDM)\n\nFDM is an intensive, sometimes painful and fast-acting, effective therapeutic approach used for both acute and chronic symptoms. This technique mainly uses the thumbs or the palm of the hand. Targeted manual techniques or manual therapeutic joint mobilisation are used to try to return the connective tissue to its original physiological shape and restore its optimal function.\n\n## 1.2 Fascial manipulation (FM)\n\nThis treatment method focuses mainly on connective tissue, particularly the deep fascia. Like FDM, it is an intensive and very effective treatment for a wide range of symptoms. Special movement tests and palpation identify areas of increased fascial tension throughout the body, which are treated with pressure and simultaneous friction. These specific tests also take earlier injuries into account: these may subsequently influence other connective-tissue structures and therefore be important within the chain of causes, requiring treatment as well.\n\n## Typical symptoms for which fascial treatment can help\n\n- All stubborn, longstanding problems for which a cause can hardly be found\n- Common problems such as heel spurs, tennis/golfer''s elbow, Achilles tendon problems, bursitis and sciatic pain, etc.\n- Sports injuries of all kinds: ankle sprains, knee injuries, hip pain, shoulder dislocation, etc."}'::jsonb, '2026-09-15 18:54:07'::timestamptz)
on conflict (collection, id) do update set
