  updated_at = excluded.updated_at;

insert into public.content (collection, id, draft, published, updated_at) values ('services', 'logopaedie', '{"id":"logopaedie","title":"Logopädie","tag":"LOGOPÄDIE IN 1010 WIEN","intro":"Die Logopädie umfasst die Beratung, Diagnostik und Therapie bei Störungen der Sprache, des Sprechens, des Schluckens, der Stimme und des Hörens unabhängig vom Alter.","body":"Unser Leben basiert zu einem sehr großen Teil auf Kommunikation. Liegt eine Störung auf einer sprachlichen Ebene vor, können unterschiedliche Einschränkungen im sozialen oder beruflichen Leben, sowie in persönlichen Beziehungen entstehen.\n\nZiel der logopädischen Behandlung ist es diese Einschränkung(en) zu vermindern oder ganz zu beseitigen.\n\n## Interdisziplinäres Arbeiten\n\nUm den größtmöglichen Erfolg einer Therapie zu erzielen, ist für eine ganzheitliche Behandlung oftmals die Zusammenarbeit mehrerer Berufsgruppen ein wichtiger Bestandteil. Durch das Verbinden von verschiedenen Fähigkeiten und Fachwissen, kann ein Patient/eine Patientin auf mehreren Ebenen therapeutisch unterstützt werden.\n\nAus der Kooperation zwischen Physiotherapie und Logopädie in der Citypraxis, ergeben sich zusätzliche Chancen zur intensiveren Behandlung verschiedener Störungsbilder.\n\n## Besonderheit der Logopädie in der Citypraxis\n\nNebst den logopädischen klassischen Techniken wird ebenfalls nach CRAFTA® (= Craniofaziales, Craniomandibuläres und Craniozervikales Manualtherapeutisches Konzept) behandelt.\n\n## Schwerpunkte Logopädie\n\n- Erworbene/neurologisch bedingte Sprach-, Schluck- und Sprechstörungen (Aphasie, Dysphagie, Dysarthrie)\n- Myofunktionelle Therapie / Orofaziale Dysfunktionen\n- (Muskuläres Gleichgewicht im Mund- und Gesichtsbereich herstellen, Erlernen der physiologischen Zungenruhelage, Anbahnung des physiologischen Schluckmusters)\n- Therapie im Bereich Kindersprache\n- (Sprachentwicklungsstörungen, Dysgrammatismus, Lexikalische Störungen, phonetisch- phonologische Störungen/Artikulationsstörungen)\n- Dysphonien\n- Stimmstörungen (Funktioneller, organischer und/oder psychogener Natur)\n- Kieferprobleme jeglicher Art\n- Vor-/ Nachbehandlung Zungenbanddurchtrennungen, etc.","methods":"","order":2,"image":"/assets/service-logo.jpg","related":"crafta","sourceUrl":"https://citypraxis.wien/","sourceDate":"2026-09-15","titleEn":"Speech & language therapy","tagEn":"SPEECH & LANGUAGE THERAPY IN 1010 VIENNA","introEn":"Speech and language therapy covers advice, diagnosis and treatment for disorders of language, speech, swallowing, voice and hearing, regardless of age.","bodyEn":"Communication is a very large part of our lives. A language-related disorder can lead to various limitations in social or working life and in personal relationships.\n\nThe aim of speech and language therapy is to reduce or completely resolve these limitations.\n\n## Interdisciplinary working\n\nTo achieve the greatest possible success, cooperation between several professional groups is often an important part of holistic treatment. By combining different skills and specialist knowledge, a patient can receive therapeutic support on several levels.\n\nThe cooperation between physiotherapy and speech and language therapy at Citypraxis creates additional opportunities for more intensive treatment of various disorders.\n\n## A special feature of speech and language therapy at Citypraxis\n\nAlongside classic speech and language therapy techniques, treatment also follows CRAFTA® (= a craniofacial, craniomandibular and craniocervical manual therapy concept).\n\n## Speech & language therapy specialisms\n\n- Acquired/neurologically caused language, swallowing and speech disorders (aphasia, dysphagia, dysarthria)\n- Myofunctional therapy / orofacial dysfunctions\n- (Establishing muscular balance in the mouth and face, learning the physiological resting position of the tongue and facilitating a physiological swallowing pattern)\n- Therapy for children''s language\n- (Language development disorders, dysgrammatism, lexical disorders, phonetic/phonological disorders and articulation disorders)\n- Dysphonia\n- Voice disorders (functional, organic and/or psychogenic)\n- Jaw problems of all kinds\n- Treatment before and after tongue-tie release, etc.","methodsEn":""}'::jsonb, '{"id":"logopaedie","title":"Logopädie","tag":"LOGOPÄDIE IN 1010 WIEN","intro":"Die Logopädie umfasst die Beratung, Diagnostik und Therapie bei Störungen der Sprache, des Sprechens, des Schluckens, der Stimme und des Hörens unabhängig vom Alter.","body":"Unser Leben basiert zu einem sehr großen Teil auf Kommunikation. Liegt eine Störung auf einer sprachlichen Ebene vor, können unterschiedliche Einschränkungen im sozialen oder beruflichen Leben, sowie in persönlichen Beziehungen entstehen.\n\nZiel der logopädischen Behandlung ist es diese Einschränkung(en) zu vermindern oder ganz zu beseitigen.\n\n## Interdisziplinäres Arbeiten\n\nUm den größtmöglichen Erfolg einer Therapie zu erzielen, ist für eine ganzheitliche Behandlung oftmals die Zusammenarbeit mehrerer Berufsgruppen ein wichtiger Bestandteil. Durch das Verbinden von verschiedenen Fähigkeiten und Fachwissen, kann ein Patient/eine Patientin auf mehreren Ebenen therapeutisch unterstützt werden.\n\nAus der Kooperation zwischen Physiotherapie und Logopädie in der Citypraxis, ergeben sich zusätzliche Chancen zur intensiveren Behandlung verschiedener Störungsbilder.\n\n## Besonderheit der Logopädie in der Citypraxis\n\nNebst den logopädischen klassischen Techniken wird ebenfalls nach CRAFTA® (= Craniofaziales, Craniomandibuläres und Craniozervikales Manualtherapeutisches Konzept) behandelt.\n\n## Schwerpunkte Logopädie\n\n- Erworbene/neurologisch bedingte Sprach-, Schluck- und Sprechstörungen (Aphasie, Dysphagie, Dysarthrie)\n- Myofunktionelle Therapie / Orofaziale Dysfunktionen\n- (Muskuläres Gleichgewicht im Mund- und Gesichtsbereich herstellen, Erlernen der physiologischen Zungenruhelage, Anbahnung des physiologischen Schluckmusters)\n- Therapie im Bereich Kindersprache\n- (Sprachentwicklungsstörungen, Dysgrammatismus, Lexikalische Störungen, phonetisch- phonologische Störungen/Artikulationsstörungen)\n- Dysphonien\n- Stimmstörungen (Funktioneller, organischer und/oder psychogener Natur)\n- Kieferprobleme jeglicher Art\n- Vor-/ Nachbehandlung Zungenbanddurchtrennungen, etc.","methods":"","order":2,"image":"/assets/service-logo.jpg","related":"crafta","sourceUrl":"https://citypraxis.wien/","sourceDate":"2026-09-15","titleEn":"Speech & language therapy","tagEn":"SPEECH & LANGUAGE THERAPY IN 1010 VIENNA","introEn":"Speech and language therapy covers advice, diagnosis and treatment for disorders of language, speech, swallowing, voice and hearing, regardless of age.","bodyEn":"Communication is a very large part of our lives. A language-related disorder can lead to various limitations in social or working life and in personal relationships.\n\nThe aim of speech and language therapy is to reduce or completely resolve these limitations.\n\n## Interdisciplinary working\n\nTo achieve the greatest possible success, cooperation between several professional groups is often an important part of holistic treatment. By combining different skills and specialist knowledge, a patient can receive therapeutic support on several levels.\n\nThe cooperation between physiotherapy and speech and language therapy at Citypraxis creates additional opportunities for more intensive treatment of various disorders.\n\n## A special feature of speech and language therapy at Citypraxis\n\nAlongside classic speech and language therapy techniques, treatment also follows CRAFTA® (= a craniofacial, craniomandibular and craniocervical manual therapy concept).\n\n## Speech & language therapy specialisms\n\n- Acquired/neurologically caused language, swallowing and speech disorders (aphasia, dysphagia, dysarthria)\n- Myofunctional therapy / orofacial dysfunctions\n- (Establishing muscular balance in the mouth and face, learning the physiological resting position of the tongue and facilitating a physiological swallowing pattern)\n- Therapy for children''s language\n- (Language development disorders, dysgrammatism, lexical disorders, phonetic/phonological disorders and articulation disorders)\n- Dysphonia\n- Voice disorders (functional, organic and/or psychogenic)\n- Jaw problems of all kinds\n- Treatment before and after tongue-tie release, etc.","methodsEn":""}'::jsonb, '2026-09-15 14:33:49'::timestamptz)
