insert into public.content (collection, id, draft, published, updated_at) values ('services', 'physiotherapie', '{"id":"physiotherapie","title":"Physiotherapie","tag":"PHYSIOTHERAPIE IN 1010 WIEN","intro":"Ziel der physiotherapeutischen Behandlung ist es, die Bewegungsfreiheit und die Funktionsfähigkeit des Körpers wiederherzustellen oder zu erhalten. Weiters die Schmerzen zu lindern, um das natürliche Gleichgewicht des Körpers zu aktivieren und dadurch insgesamt eine Verbesserung des Allgemeinzustandes zu erreichen. Diese Funktionen des Körpers können z.B. durch einen Unfall, eine Operation, ein seelisches Trauma, angeborene Entwicklungsstörungen oder im Alltag erworbene Fehlhaltungen beeinträchtigt werden.","body":"Durch die unterschiedlichen Anwendungsformen in der Physiotherapie können beispielsweise Muskelspannungen reduziert, Asynchronitäten verbessert, Körperwahrnehmungen geschult, Fehlbelastungen korrigiert, gesunde Bewegungsabläufe wiedererlernt, haltungsbedingte Defizite beseitigt, unausgewogene Muskelkraftverhältnisse angeglichen werden und vieles mehr.\n\n## Physiotherapie findet ihren Anwendungsbereich allgemein in der:\n\n- Prävention (Alltag und Berufsleben)\n- Prä-/Postoperativen Versorgung\n- Behandlung akuter wie chronischer Krankheitsbilder\n- im Sport\n\n## Behandlungskonzepte in der Physiotherapie\n\n- 1.) Faszienbehandlungen\n- 2.) Craniofaziale Therapie (=CRAFTA®)\n- 3.) Craniomandibuläres (=CMD) Konzept\n- 4.) Manualtherapie nach Maitland\n- 5.) Sportphysiotherapie\n- 6.) Rückenfitkurs - in Gruppentherapie","methods":"","order":0,"image":"/assets/service-physio.jpg","related":"faszienbehandlungen,crafta,cmd,rueckenfit","sourceUrl":"https://citypraxis.wien/","sourceDate":"2026-09-15","titleEn":"Physiotherapy","tagEn":"PHYSIOTHERAPY IN 1010 VIENNA","introEn":"The aim of physiotherapy is to restore or maintain freedom of movement and the functional capacity of the body. It also aims to relieve pain, activate the body’s natural balance and thereby improve overall wellbeing. These bodily functions can be affected, for example, by an accident, surgery, emotional trauma, congenital developmental disorders or poor posture acquired in everyday life.","bodyEn":"The different applications of physiotherapy can, for example, reduce muscle tension, improve coordination imbalances, train body awareness, correct inappropriate loading, help people relearn healthy movement patterns, address posture-related deficits, balance unequal muscle strength and much more.\n\n## Physiotherapy is generally used in:\n\n- Prevention (everyday and working life)\n- Pre- and postoperative care\n- Treatment of acute and chronic conditions\n- Sport\n\n## Treatment approaches in physiotherapy\n\n- 1.) Fascial treatments\n- 2.) Craniofacial therapy (= CRAFTA®)\n- 3.) Craniomandibular (= CMD) concept\n- 4.) Maitland manual therapy\n- 5.) Sports physiotherapy\n- 6.) Back fitness course — group therapy","methodsEn":""}'::jsonb, '{"id":"physiotherapie","title":"Physiotherapie","tag":"PHYSIOTHERAPIE IN 1010 WIEN","intro":"Ziel der physiotherapeutischen Behandlung ist es, die Bewegungsfreiheit und die Funktionsfähigkeit des Körpers wiederherzustellen oder zu erhalten. Weiters die Schmerzen zu lindern, um das natürliche Gleichgewicht des Körpers zu aktivieren und dadurch insgesamt eine Verbesserung des Allgemeinzustandes zu erreichen. Diese Funktionen des Körpers können z.B. durch einen Unfall, eine Operation, ein seelisches Trauma, angeborene Entwicklungsstörungen oder im Alltag erworbene Fehlhaltungen beeinträchtigt werden.","body":"Durch die unterschiedlichen Anwendungsformen in der Physiotherapie können beispielsweise Muskelspannungen reduziert, Asynchronitäten verbessert, Körperwahrnehmungen geschult, Fehlbelastungen korrigiert, gesunde Bewegungsabläufe wiedererlernt, haltungsbedingte Defizite beseitigt, unausgewogene Muskelkraftverhältnisse angeglichen werden und vieles mehr.\n\n## Physiotherapie findet ihren Anwendungsbereich allgemein in der:\n\n- Prävention (Alltag und Berufsleben)\n- Prä-/Postoperativen Versorgung\n- Behandlung akuter wie chronischer Krankheitsbilder\n- im Sport\n\n## Behandlungskonzepte in der Physiotherapie\n\n- 1.) Faszienbehandlungen\n- 2.) Craniofaziale Therapie (=CRAFTA®)\n- 3.) Craniomandibuläres (=CMD) Konzept\n- 4.) Manualtherapie nach Maitland\n- 5.) Sportphysiotherapie\n- 6.) Rückenfitkurs - in Gruppentherapie","methods":"","order":0,"image":"/assets/service-physio.jpg","related":"faszienbehandlungen,crafta,cmd,rueckenfit","sourceUrl":"https://citypraxis.wien/","sourceDate":"2026-09-15","titleEn":"Physiotherapy","tagEn":"PHYSIOTHERAPY IN 1010 VIENNA","introEn":"The aim of physiotherapy is to restore or maintain freedom of movement and the functional capacity of the body. It also aims to relieve pain, activate the body’s natural balance and thereby improve overall wellbeing. These bodily functions can be affected, for example, by an accident, surgery, emotional trauma, congenital developmental disorders or poor posture acquired in everyday life.","bodyEn":"The different applications of physiotherapy can, for example, reduce muscle tension, improve coordination imbalances, train body awareness, correct inappropriate loading, help people relearn healthy movement patterns, address posture-related deficits, balance unequal muscle strength and much more.\n\n## Physiotherapy is generally used in:\n\n- Prevention (everyday and working life)\n- Pre- and postoperative care\n- Treatment of acute and chronic conditions\n- Sport\n\n## Treatment approaches in physiotherapy\n\n- 1.) Fascial treatments\n- 2.) Craniofacial therapy (= CRAFTA®)\n- 3.) Craniomandibular (= CMD) concept\n- 4.) Maitland manual therapy\n- 5.) Sports physiotherapy\n- 6.) Back fitness course — group therapy","methodsEn":""}'::jsonb, '2026-09-15 14:33:49'::timestamptz)
