insert into public.content (collection, id, draft, published, updated_at) values ('services', 'rueckenfit', '{"id":"rueckenfit","title":"Rückenfit Kurs","tag":"BEWEGUNG IN DER GRUPPE","intro":"In dieser 10-teiligen aufbauenden Kursreihe (inkl. 11. Einheit gratis) sollen Sie allgemeine Erfahrungen zum Thema Rumpfkräftigung und Wirbelsäulenstabilierung sammeln. Sie erlernen einfache Übungen zur Heimanwendung, sowie Übungen für Ihren Arbeitsalltag. Dieser Kurs dient sowohl der Prävention als auch bei Vorbelastungen im Bereich der Wirbelsäule.","body":"## Kosten\n\n€ 250 für 10 Einheiten plus 11. Einheit gratis\n\n## Wichtige Infos zu diesem Kurs:\n\nFür diesen Kurs sind keinerlei Vorkenntnisse notwendig und er ist für jede Altersgruppe geeignet.\n\nBequeme Kleidung + Handtuch erforderlich\n\nWenn Sie immer wieder unter einem der folgenden Symptome leiden, eignet sich der Rückenfit - Kurs besonders für Sie:\n\n- Rückenverspannungen, Lumbago, Dorsalgie\n- alle nicht akute Schmerzzustände\n- Nackenverspannungen und Kopfschmerzen durch Fehlhaltungen\n\n## Gesundheitshunderter SVS:\n\nWenn Sie bei der SVS VertragspartnerIn sind, können Sie die Rechnung über den Rückenfitkurs bei der SVS einreichen und erhalten 100€ von der SVS rückvergütet.","methods":"","order":4,"image":"/assets/service-rueckenfit.jpg","sourceUrl":"https://citypraxis.wien/","sourceDate":"2026-09-15","titleEn":"Back fitness","tagEn":"GROUP THERAPY","introEn":"In this progressive 10-part course (including an 11th session free), you will learn about strengthening the core and stabilising the spine.","bodyEn":"You will learn simple exercises to use at home and in your workplace. This course supports both prevention and existing problems affecting the spine.\n\n## Cost\n\n€250 for 10 sessions plus the 11th session free.\n\n## Important course information\n\nNo previous experience is required, and the course is suitable for all age groups.\n\nComfortable clothing and a towel are required.\n\nIf you repeatedly experience any of the following symptoms, the back fitness course is particularly suitable for you:\n\n- Back tension, lumbago, dorsalgia\n- All non-acute pain conditions\n- Neck tension and headaches caused by poor posture\n\n## SVS Gesundheitshunderter\n\nIf you are insured with SVS, you can submit the invoice for the back fitness course to SVS and receive a €100 reimbursement.","methodsEn":""}'::jsonb, '{"id":"rueckenfit","title":"Rückenfit Kurs","tag":"BEWEGUNG IN DER GRUPPE","intro":"In dieser 10-teiligen aufbauenden Kursreihe (inkl. 11. Einheit gratis) sollen Sie allgemeine Erfahrungen zum Thema Rumpfkräftigung und Wirbelsäulenstabilierung sammeln. Sie erlernen einfache Übungen zur Heimanwendung, sowie Übungen für Ihren Arbeitsalltag. Dieser Kurs dient sowohl der Prävention als auch bei Vorbelastungen im Bereich der Wirbelsäule.","body":"## Kosten\n\n€ 250 für 10 Einheiten plus 11. Einheit gratis\n\n## Wichtige Infos zu diesem Kurs:\n\nFür diesen Kurs sind keinerlei Vorkenntnisse notwendig und er ist für jede Altersgruppe geeignet.\n\nBequeme Kleidung + Handtuch erforderlich\n\nWenn Sie immer wieder unter einem der folgenden Symptome leiden, eignet sich der Rückenfit - Kurs besonders für Sie:\n\n- Rückenverspannungen, Lumbago, Dorsalgie\n- alle nicht akute Schmerzzustände\n- Nackenverspannungen und Kopfschmerzen durch Fehlhaltungen\n\n## Gesundheitshunderter SVS:\n\nWenn Sie bei der SVS VertragspartnerIn sind, können Sie die Rechnung über den Rückenfitkurs bei der SVS einreichen und erhalten 100€ von der SVS rückvergütet.","methods":"","order":4,"image":"/assets/service-rueckenfit.jpg","sourceUrl":"https://citypraxis.wien/","sourceDate":"2026-09-15","titleEn":"Back fitness","tagEn":"GROUP THERAPY","introEn":"In this progressive 10-part course (including an 11th session free), you will learn about strengthening the core and stabilising the spine.","bodyEn":"You will learn simple exercises to use at home and in your workplace. This course supports both prevention and existing problems affecting the spine.\n\n## Cost\n\n€250 for 10 sessions plus the 11th session free.\n\n## Important course information\n\nNo previous experience is required, and the course is suitable for all age groups.\n\nComfortable clothing and a towel are required.\n\nIf you repeatedly experience any of the following symptoms, the back fitness course is particularly suitable for you:\n\n- Back tension, lumbago, dorsalgia\n- All non-acute pain conditions\n- Neck tension and headaches caused by poor posture\n\n## SVS Gesundheitshunderter\n\nIf you are insured with SVS, you can submit the invoice for the back fitness course to SVS and receive a €100 reimbursement.","methodsEn":""}'::jsonb, '2026-09-15 14:33:49'::timestamptz)
