insert into public.content (collection, id, draft, published, updated_at) values ('symptoms', 'kiefer', '{"id":"kiefer","title":"Kiefer","subtitle":"Wenn sich Anspannung festsetzt.","intro":"Kieferknacken, Zähneknirschen oder Beschwerden beim Öffnen des Mundes? Wir betrachten das Zusammenspiel von Kiefer, Kopf und Nacken.","body":"Am Anfang stehen ein Gespräch und eine individuelle Untersuchung. Gemeinsam besprechen wir, welche therapeutischen Schritte zu Ihrer Situation passen.\n\nUnsere Schwerpunkte umfassen craniomandibuläre und craniofaziale Beschwerden. Je nach Befund verbinden wir physiotherapeutische und logopädische Perspektiven.","service":"physiotherapie","icon":"jaw","order":0,"titleEn":"Jaw","subtitleEn":"When tension takes hold.","introEn":"Jaw clicking, teeth grinding or pain when opening your mouth? We consider how the jaw, head and neck work together.","bodyEn":"We start with a conversation and an individual examination. Together, we discuss which therapeutic steps suit your situation.\n\nOur specialisms include craniomandibular and craniofacial symptoms. Depending on the findings, we combine physiotherapy and speech and language therapy perspectives."}'::jsonb, '{"id":"kiefer","title":"Kiefer","subtitle":"Wenn sich Anspannung festsetzt.","intro":"Kieferknacken, Zähneknirschen oder Beschwerden beim Öffnen des Mundes? Wir betrachten das Zusammenspiel von Kiefer, Kopf und Nacken.","body":"Am Anfang stehen ein Gespräch und eine individuelle Untersuchung. Gemeinsam besprechen wir, welche therapeutischen Schritte zu Ihrer Situation passen.\n\nUnsere Schwerpunkte umfassen craniomandibuläre und craniofaziale Beschwerden. Je nach Befund verbinden wir physiotherapeutische und logopädische Perspektiven.","service":"physiotherapie","icon":"jaw","order":0,"titleEn":"Jaw","subtitleEn":"When tension takes hold.","introEn":"Jaw clicking, teeth grinding or pain when opening your mouth? We consider how the jaw, head and neck work together.","bodyEn":"We start with a conversation and an individual examination. Together, we discuss which therapeutic steps suit your situation.\n\nOur specialisms include craniomandibular and craniofacial symptoms. Depending on the findings, we combine physiotherapy and speech and language therapy perspectives."}'::jsonb, '2026-09-15 14:33:49'::timestamptz)
on conflict (collection, id) do update set
  draft = excluded.draft,
  published = excluded.published,
  updated_at = excluded.updated_at;

insert into public.content (collection, id, draft, published, updated_at) values ('symptoms', 'kopfschmerzen', '{"id":"kopfschmerzen","title":"Kopf & Migräne","subtitle":"Raum für einen klareren Kopf.","intro":"Wiederkehrende Kopf- und Nackenbeschwerden können den Alltag stark beeinflussen. Wir nehmen uns Zeit für Ihre Geschichte.","body":"Wir untersuchen mögliche Zusammenhänge im Bereich von Nacken, Kiefer und Bewegung. Auf Basis Ihres Befundes und Ihrer ärztlichen Abklärung planen wir gemeinsam die Therapie.\n\nNicht jeder Kopfschmerz hat dieselbe Ursache. Die Behandlung wird deshalb an Ihre individuelle Situation angepasst.","service":"physiotherapie","icon":"head","order":1,"titleEn":"Headaches & migraine","subtitleEn":"Space for a clearer head.","introEn":"Recurring head and neck symptoms can have a considerable effect on everyday life. We take time to listen to your history.","bodyEn":"We examine possible connections involving the neck, jaw and movement. Based on our findings and your medical assessment, we plan your therapy together.\n\nNot every headache has the same cause. Treatment is therefore adapted to your individual situation."}'::jsonb, '{"id":"kopfschmerzen","title":"Kopf & Migräne","subtitle":"Raum für einen klareren Kopf.","intro":"Wiederkehrende Kopf- und Nackenbeschwerden können den Alltag stark beeinflussen. Wir nehmen uns Zeit für Ihre Geschichte.","body":"Wir untersuchen mögliche Zusammenhänge im Bereich von Nacken, Kiefer und Bewegung. Auf Basis Ihres Befundes und Ihrer ärztlichen Abklärung planen wir gemeinsam die Therapie.\n\nNicht jeder Kopfschmerz hat dieselbe Ursache. Die Behandlung wird deshalb an Ihre individuelle Situation angepasst.","service":"physiotherapie","icon":"head","order":1,"titleEn":"Headaches & migraine","subtitleEn":"Space for a clearer head.","introEn":"Recurring head and neck symptoms can have a considerable effect on everyday life. We take time to listen to your history.","bodyEn":"We examine possible connections involving the neck, jaw and movement. Based on our findings and your medical assessment, we plan your therapy together.\n\nNot every headache has the same cause. Treatment is therefore adapted to your individual situation."}'::jsonb, '2026-09-15 14:33:49'::timestamptz)
on conflict (collection, id) do update set
  draft = excluded.draft,
  published = excluded.published,
  updated_at = excluded.updated_at;

insert into public.content (collection, id, draft, published, updated_at) values ('symptoms', 'schwindel', '{"id":"schwindel","title":"Schwindel","subtitle":"Wieder mehr Sicherheit finden.","intro":"Wir begleiten Sie bei ärztlich abgeklärten Schwindelbeschwerden mit einem individuell abgestimmten Therapieansatz.","body":"Schwindel kann unterschiedliche Ursachen haben. Deshalb sind die ärztliche Abklärung und eine sorgfältige Untersuchung wichtige Grundlagen.\n\nGemeinsam arbeiten wir an den für Sie relevanten Bewegungen und Alltagssituationen.","service":"physiotherapie","icon":"balance","order":3,"titleEn":"Dizziness","subtitleEn":"Finding greater confidence again.","introEn":"We support you with an individually tailored approach to dizziness that has been medically assessed.","bodyEn":"Dizziness can have different causes. Medical assessment and a careful examination are therefore important foundations.\n\nTogether, we work on the movements and everyday situations that matter to you."}'::jsonb, '{"id":"schwindel","title":"Schwindel","subtitle":"Wieder mehr Sicherheit finden.","intro":"Wir begleiten Sie bei ärztlich abgeklärten Schwindelbeschwerden mit einem individuell abgestimmten Therapieansatz.","body":"Schwindel kann unterschiedliche Ursachen haben. Deshalb sind die ärztliche Abklärung und eine sorgfältige Untersuchung wichtige Grundlagen.\n\nGemeinsam arbeiten wir an den für Sie relevanten Bewegungen und Alltagssituationen.","service":"physiotherapie","icon":"balance","order":3,"titleEn":"Dizziness","subtitleEn":"Finding greater confidence again.","introEn":"We support you with an individually tailored approach to dizziness that has been medically assessed.","bodyEn":"Dizziness can have different causes. Medical assessment and a careful examination are therefore important foundations.\n\nTogether, we work on the movements and everyday situations that matter to you."}'::jsonb, '2026-09-15 14:33:49'::timestamptz)
on conflict (collection, id) do update set
  draft = excluded.draft,
  published = excluded.published,
  updated_at = excluded.updated_at;

insert into public.content (collection, id, draft, published, updated_at) values ('symptoms', 'tinnitus', '{"id":"tinnitus","title":"Tinnitus","subtitle":"Zusammenhänge verstehen.","intro":"Bei Ohrgeräuschen kann es sinnvoll sein, auch Kiefer und Halswirbelsäule in die Untersuchung einzubeziehen.","body":"Nach ärztlicher Abklärung betrachten wir mögliche funktionelle Zusammenhänge. Die Auswahl der therapeutischen Maßnahmen richtet sich nach Ihrem individuellen Befund.\n\nEine Behandlung ist keine Garantie dafür, dass Ohrgeräusche verschwinden. Wir besprechen Möglichkeiten und Ziele offen mit Ihnen.","service":"physiotherapie","icon":"ear","order":2,"titleEn":"Tinnitus","subtitleEn":"Understanding the connections.","introEn":"With ringing in the ears, it can be useful to include the jaw and cervical spine in the examination.","bodyEn":"Following medical assessment, we consider possible functional connections. Therapeutic measures are selected according to your individual findings.\n\nTreatment does not guarantee that tinnitus will disappear. We discuss the options and goals openly with you."}'::jsonb, '{"id":"tinnitus","title":"Tinnitus","subtitle":"Zusammenhänge verstehen.","intro":"Bei Ohrgeräuschen kann es sinnvoll sein, auch Kiefer und Halswirbelsäule in die Untersuchung einzubeziehen.","body":"Nach ärztlicher Abklärung betrachten wir mögliche funktionelle Zusammenhänge. Die Auswahl der therapeutischen Maßnahmen richtet sich nach Ihrem individuellen Befund.\n\nEine Behandlung ist keine Garantie dafür, dass Ohrgeräusche verschwinden. Wir besprechen Möglichkeiten und Ziele offen mit Ihnen.","service":"physiotherapie","icon":"ear","order":2,"titleEn":"Tinnitus","subtitleEn":"Understanding the connections.","introEn":"With ringing in the ears, it can be useful to include the jaw and cervical spine in the examination.","bodyEn":"Following medical assessment, we consider possible functional connections. Therapeutic measures are selected according to your individual findings.\n\nTreatment does not guarantee that tinnitus will disappear. We discuss the options and goals openly with you."}'::jsonb, '2026-09-15 14:33:49'::timestamptz)
on conflict (collection, id) do update set
  draft = excluded.draft,
  published = excluded.published,
  updated_at = excluded.updated_at;

insert into public.content (collection, id, draft, published, updated_at) values ('symptoms', 'unfall-operation', '{"id":"unfall-operation","title":"Unfall & OP","subtitle":"Schritt für Schritt zurück.","intro":"Nach einer Verletzung oder Operation unterstützen wir Sie dabei, Bewegung und Vertrauen in Ihren Körper zurückzugewinnen.","body":"Wir stimmen die Therapie auf den Heilungsverlauf, ärztliche Vorgaben und Ihre persönlichen Ziele ab.\n\nBeweglichkeit, Kraft und die Anforderungen Ihres Alltags bilden dabei den Ausgangspunkt für einen gemeinsamen Plan.","service":"physiotherapie","icon":"movement","order":4,"titleEn":"Injury & surgery","subtitleEn":"Step by step, back to everyday life.","introEn":"After an injury or operation, we help you regain movement and confidence in your body.","bodyEn":"We adapt therapy to your healing process, medical instructions and personal goals.\n\nMobility, strength and the demands of your everyday life form the starting point for a shared plan."}'::jsonb, '{"id":"unfall-operation","title":"Unfall & OP","subtitle":"Schritt für Schritt zurück.","intro":"Nach einer Verletzung oder Operation unterstützen wir Sie dabei, Bewegung und Vertrauen in Ihren Körper zurückzugewinnen.","body":"Wir stimmen die Therapie auf den Heilungsverlauf, ärztliche Vorgaben und Ihre persönlichen Ziele ab.\n\nBeweglichkeit, Kraft und die Anforderungen Ihres Alltags bilden dabei den Ausgangspunkt für einen gemeinsamen Plan.","service":"physiotherapie","icon":"movement","order":4,"titleEn":"Injury & surgery","subtitleEn":"Step by step, back to everyday life.","introEn":"After an injury or operation, we help you regain movement and confidence in your body.","bodyEn":"We adapt therapy to your healing process, medical instructions and personal goals.\n\nMobility, strength and the demands of your everyday life form the starting point for a shared plan."}'::jsonb, '2026-09-15 14:33:49'::timestamptz)
on conflict (collection, id) do update set
  draft = excluded.draft,
  published = excluded.published,
  updated_at = excluded.updated_at;

